pub fn solve() {
    let mut writer = FastOutput::stdout();
    let mut scanner = unsafe { FastInput::stdin() };
    let n = unsafe { scanner.usize() };
    let q = unsafe { scanner.usize() };
    let a: Vec<_> = (0..n).map(|_| unsafe { scanner.u32() }).collect();
    let lrk = (0..q).map(|_| unsafe {
        let l = scanner.u32_small();
        let r = scanner.u32_small();
        let k = scanner.u32_small();
        (l as usize..r as usize, k as usize)
    });
    let wm = WaveletMatrix::new(a);
    for res in wm.quantile_batch(lrk) {
        writer.u32(res);
        writer.byte(b'\n');
    }
}
